use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── dispatch: a runtime bool branching around a large inlinable
        // body forces the inliner into duplicate-or-deinline; the fix
        // moves the branch INTO the setup (a conditional guard), leaving
        // ONE body text with ONE call site.
        // Source: bevyengine/bevy #25864 (function_system.rs).
        PerfRule {
            rule_id: "runtime-bool-duplicates-inlinable-body".to_string(),
            name: "a runtime bool branching around a large inlinable body forces the inliner to either inline TWO copies of the body (one per branch, code bloat) or leave it a non-inlined call — restructure so the branch guards only the SETUP (a conditional `Option<Guard>` / tuple), and the body exists once with one call site".to_string(),
            category: "dispatch".to_string(),
            buggy_code: "// naive: `run_impl` is inlinable and shared by both arms, but the RUNTIME\n// bool branches AROUND it. LLVM must either inline two copies (one per\n// branch — code bloat, I-cache pressure) or give up and emit a real\n// call — bevy #25864 review, verbatim: 'Normally the system and\n// `get_param` all get inlined together, but since `self.is_exclusive`\n// is a runtime check this will have to either inline *two* copies of\n// the system, or leave it as a non-inlined function call.'\npub struct World {\n    pub value: u32,\n    pub change_tick: u32,\n    pub last_change_tick: u32,\n}\n\npub struct System {\n    pub is_exclusive: bool,\n    pub last_run: u32,\n}\n\n// a large inlinable body: param fetch + the system fn + result conversion\nfn run_impl(world: &mut World, input: u32, tick: u32) -> u32 {\n    world.change_tick = tick;\n    world.value = input.wrapping_mul(2654435761) ^ world.last_change_tick;\n    world.value\n}\n\nimpl System {\n    // the branch WRAPS the inlinable body: two copies or no inlining.\n    pub fn run(&mut self, world: &mut World, input: u32) -> u32 {\n        let out = if self.is_exclusive {\n            // exclusive-only bookkeeping wrapped around the same body\n            let saved = world.last_change_tick;\n            world.last_change_tick = self.last_run;\n            let out = run_impl(world, input, world.change_tick);\n            world.last_change_tick = saved;\n            out\n        } else {\n            run_impl(world, input, world.change_tick.wrapping_add(1))\n        };\n        self.last_run = 1;\n        out\n    }\n}\n\n#[test]\nfn both_branches_still_compute() {\n    let mut w = World { value: 0, change_tick: 7, last_change_tick: 3 };\n    let mut s = System { is_exclusive: true, last_run: 3 };\n    assert_eq!(s.run(&mut w, 5), (5u32.wrapping_mul(2654435761) ^ 3));\n    s.is_exclusive = false;\n    assert_eq!(s.run(&mut w, 5), (5u32.wrapping_mul(2654435761) ^ 3));\n}\n"
                .to_string(),
            fixed_code: "// optimized: the branch moves INTO the setup — a conditional guard\n// carries the exclusive-only bookkeeping (None in the plain arm), and\n// the body is written ONCE and called ONCE: a single call site for the\n// inliner to fold. The landed bevy form (patch 2): `let (change_tick,\n// _guard) = if self.is_exclusive { (tick, Some(LastTickGuard { .. })) }\n// else { (world.increment_change_tick(), None) };` then the one `run`\n// body outside the branch — the guard restores via Drop so the reset\n// happens 'regardless of whether the system completes successfully or\n// panics' (in-code comment verbatim).\npub struct World {\n    pub value: u32,\n    pub change_tick: u32,\n    pub last_change_tick: u32,\n}\n\npub struct System {\n    pub is_exclusive: bool,\n    pub last_run: u32,\n}\n\nfn run_impl(world: &mut World, input: u32, tick: u32) -> u32 {\n    world.change_tick = tick;\n    world.value = input.wrapping_mul(2654435761) ^ world.last_change_tick;\n    world.value\n}\n\n// the exclusive-only setup, conditionally constructed — restore on\n// drop, 'even if a panic occurs during the scope' (in-code comment).\nstruct LastTickGuard {\n    world: *mut World,\n    last_tick: u32,\n}\n\nimpl Drop for LastTickGuard {\n    fn drop(&mut self) {\n        // SAFETY: created under exclusive world access (the bevy guard\n        // holds an UnsafeWorldCell with the same premise); nothing else\n        // touches the world while the guard lives.\n        unsafe {\n            (*self.world).last_change_tick = self.last_tick;\n        }\n    }\n}\n\nimpl System {\n    pub fn run(&mut self, world: &mut World, input: u32) -> u32 {\n        let _guard = self.is_exclusive.then(|| LastTickGuard {\n            world,\n            last_tick: world.last_change_tick,\n        });\n        // ONE body, ONE call site — the branch never duplicates it.\n        let out = run_impl(world, input, world.change_tick.wrapping_add(1));\n        self.last_run = world.change_tick;\n        out\n    }\n}\n\n#[test]\nfn one_body_both_postures() {\n    let mut w = World { value: 0, change_tick: 7, last_change_tick: 3 };\n    let mut s = System { is_exclusive: true, last_run: 3 };\n    assert_eq!(s.run(&mut w, 5), (5u32.wrapping_mul(2654435761) ^ 3));\n    assert_eq!(w.last_change_tick, 3); // the guard restored it\n    s.is_exclusive = false;\n    assert_eq!(s.run(&mut w, 5), (5u32.wrapping_mul(2654435761) ^ 3));\n}\n"
                .to_string(),
            context_notes: Some("Grade B− — NotBenchable on this box (a codegen-shape claim: duplicate-inline vs deinline is decided by LLVM's inliner cost model over the REAL body; a microbench of fixture stand-ins measures nothing the law asserts — the B182/186 annotation class). THE CLASS, verbatim (chescock's review, read at the PR comments API this session): 'Normally the system and `get_param` all get inlined together, but since `self.is_exclusive` is a runtime check this will have to either inline *two* copies of the system, or leave it as a non-inlined function call.' + the fix sketch: 'let _guard = self.is_exclusive.then(|| { // Set `world.last_change_tick` and create a guard to set it back using `UnsafeWorldCell` }); run(world)?;' + 'That should ensure that `run` is only compiled in once.' + the author's confirmation: 'Yep that works pretty well, changed!'. THE LANDED SHAPE IS RICHER THAN THE SKETCH (both .patch files read in full this session): patch 1 (a4d1789) moved the body into a `run` closure called from BOTH branches of `if self.is_exclusive { .. last_change_tick_scope(last_run, |w| run(..)) } else { run(..) }` — ITSELF the duplicated-body anti-shape; patch 2 (8328184) landed the real form: the branch hoisted into TUPLE construction ('let (change_tick, _guard) = if self.is_exclusive { .. Some(LastTickGuard { world, last_tick: previous_tick }) } else { (world.increment_change_tick(), None) };'), ONE `run` body outside the branch, the restore in a Drop impl whose in-code comments are the law: 'This guard is used by exclusive systems to temporarily set the world's last change tick to the system's last run tick, and then restore it when the system finishes running, regardless of whether the system completes successfully or panics.' + 'By setting the change tick in the drop impl, we ensure that the change tick gets reset even if a panic occurs during the scope.' The predicate is also resolved ONCE at initialize() ('self.is_exclusive = access.is_exclusive();') so the run path branches on a plain field. SUGGEST-ONLY by nature: the pattern match is trivial, the WIN premise (body large enough to matter, called hot enough) is not statically decidable — present as a documented pattern. THE HONEST BOUND: for small bodies LLVM may inline both copies cheaply or the branch may predict perfectly — the rule claims the SHAPE hazard, never a measured win; measure after restructuring, never before reading the assembly. KINSHIP (grep-verified in this corpus, do not double-count): inline-hint-not-through-unmarked-wrapper (B207, dispatch) is the hint-PROPAGATION axis — the inliner is blocked at an unmarked HOP; THIS is the body-DUPLICATION axis — the inliner is forced to choose between two copies and one call by a SURROUNDING branch; dyn-to-enum (entries_01) owns call-site ELIGIBILITY via static dispatch; mir-destprop-branch-site-merge (B99) pulls the OPPOSITE direction on ITS axis — it SPLITS two known call sites of a fn pointer so each site keeps its own branch-target history, so do not 'deduplicate' a fn-pointer dispatch table by this rule's shape (B99's premise is per-site predictor history; this rule's premise is ONE inlinable body wrapped by a branch — different structures); branchless-conditional is the data-level select (cmov) — unrelated axis. REGIME: a hot inlinable body shared by a rare-setup branch and a plain path (system/scheduler run loops, request handlers with a rare retry/audit wrapper, per-frame hooks with a debug/instrumented arm). ANTI-REGIME: bodies with REAL per-arm differences (the arms genuinely diverge — the duplication is the semantics); fn-pointer/vtable dispatch tables (B99's axis — call-site diversity is wanted); cold bodies (the inliner gives up either way and nobody pays). Fixtures ORIGINAL (the tick-guard shape transcribed as a plain-Rust stand-in; bevy's UnsafeWorldCell machinery is not pasted — the guard carries a raw pointer with the SAFETY premise commented). CITE: bevyengine/bevy #25864, 'Fix exclusive system change detection' (merged 2026-09-28T07:07:36Z @ 74884ffda7831d2b4576ade270199d671bb2e8f9) -- patches a4d1789badfe64fbd582a3b58525a93988fd90c0 + 8328184452b07def3ae670af95e2b8735f8c4b15, crates/bevy_ecs/src/system/function_system.rs (the LastTickGuard + the conditional tuple) + the review thread (chescock, 2026-09-21), Apache-2.0/MIT. Batch 221 / Plan 221.".to_string()),
            // Not benchable on this box: the duplicate-vs-deinline decision
            // is LLVM's inliner cost model over the real body — a stand-in
            // microbench measures nothing the law asserts (the B182 class).
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
